import React, { useEffect, useState } from 'react';
import '../styles/home.css';

import {
  FaHome,
  FaSearch,
  FaCompass,
  FaVideo,
  FaPaperPlane,
  FaHeart,
  FaPlusSquare,
  FaUser,
  FaBars,
  FaRobot,
  FaThreads
} from 'react-icons/fa';

const Home = () => {
  const [posts, setPosts] = useState([]);
  const [suggestions, setSuggestions] = useState([]);
  const [likedPosts, setLikedPosts] = useState([]);

  useEffect(() => {
    setPosts([
      {
        id: 1,
        user: 'Aman',
        content: 'Just got placed at Amazon!',
        image: 'https://source.unsplash.com/400x300/?amazon,office',
        likes: 10,
        comments: 2,
        time: '2h ago',
      },
      {
        id: 2,
        user: 'Simran',
        content: 'Join my DSA bootcamp!',
        image: 'https://source.unsplash.com/400x300/?code,bootcamp',
        likes: 5,
        comments: 1,
        time: '5h ago',
      },
    ]);

    setSuggestions([
      { id: 1, name: 'Harpreet Singh', avatar: 'https://i.pravatar.cc/40?img=1' },
      { id: 2, name: 'Mandeep Kaur', avatar: 'https://i.pravatar.cc/40?img=2' },
    ]);
  }, []);

  const handleLike = (postId) => {
    if (likedPosts.includes(postId)) {
      setLikedPosts(likedPosts.filter(id => id !== postId));
    } else {
      setLikedPosts([...likedPosts, postId]);
    }
  };

  return (
    <div className="home-wrapper">
      {/* Left Sidebar */}
      <aside className="left-sidebar">
        <div className="logo">CAMPUS NETWORK</div>
        <nav className="nav-menu">
          <div className="nav-item"><FaHome /><span>Home</span></div>
          <div className="nav-item"><FaSearch /><span>Search</span></div>
          <div className="nav-item"><FaCompass /><span>Explore</span></div>
          <div className="nav-item"><FaVideo /><span>Reels</span></div>
          <div className="nav-item"><FaPaperPlane /><span>Messages</span></div>
          <div className="nav-item"><FaHeart /><span>Notifications</span></div>
          <div className="nav-item"><FaPlusSquare /><span>Create</span></div>
          <div className="nav-item"><FaUser /><span>Profile</span></div>
          <div className="nav-item"><FaRobot /><span>AI Studio</span></div>
          <div className="nav-item"><FaThreads /><span>Threads</span></div>
          <div className="nav-item"><FaBars /><span>More</span></div>
        </nav>
      </aside>

      {/* Main Content */}
      <main className="main-content">
        {/* Header with Stories */}
        <header className="header">
          <div className="stories">
            <h4>Stories</h4>
            <div className="stories-scroll">
              {[...Array(8)].map((_, i) => (
                <div className="story" key={i}>
                  <img src={`https://i.pravatar.cc/60?img=${i + 3}`} alt="story" />
                  <span>User{i + 1}</span>
                </div>
              ))}
            </div>
          </div>
        </header>

        {/* Feed Posts */}
        <section className="main-feed">
          {posts.map(post => (
            <div className="post-card" key={post.id}>
              <div className="post-header">
                <img src={`https://i.pravatar.cc/30?u=${post.user}`} alt="avatar" />
                <span>{post.user}</span>
              </div>
              <img src={post.image} alt="post" className="post-image" />
              <div className="post-actions">
                <span
                  className={`action-icon ${likedPosts.includes(post.id) ? 'liked' : ''}`}
                  onClick={() => handleLike(post.id)}
                >
                  ❤️
                </span>
                <span className="action-icon">💬</span>
                <span className="action-icon">🔗</span>
              </div>
              <div className="post-content">
                <p>{post.content}</p>
                <div className="post-meta">
                  ❤️ {likedPosts.includes(post.id) ? post.likes + 1 : post.likes} · 💬 {post.comments} · ⏰ {post.time}
                </div>
              </div>
            </div>
          ))}
        </section>
      </main>

      {/* Right Sidebar */}
      <aside className="right-sidebar">
        <div className="profile-summary">
          <img src="https://i.pravatar.cc/40?img=10" alt="me" />
          <div>
            <strong>you_user</strong>
            <small>Your Name</small>
          </div>
        </div>
        <h4>Suggestions</h4>
        {suggestions.map(s => (
          <div className="suggestion" key={s.id}>
            <img src={s.avatar} alt="sugg" />
            <span>{s.name}</span>
            <button>Follow</button>
          </div>
        ))}
      </aside>
    </div>
  );
};

export default Home;
